head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.key_row = '';
scwin.isur_id = '';
scwin.corp_usr_tp_cd = '';
scwin.contn_id = '';
scwin.contn_grp_id = '';
scwin.ans_obj_contn_id = '';
scwin.noti_obj_sys_tp_cd = '';
scwin.ques_bz_tp_cd = '';
scwin.opn_yn = '';
scwin.gEmpNo = js_emp_no;

//////////////////////////////////////
scwin.mode = frame.opener.scwin.mode; // ex) I 인서트, U 업데이트

//////////////////////////////////////

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.libRoundPanel.PanelToGroupBox(panel_1);
        scwin.setCode();
        await scwin.initPage();
        if (scwin.mode !== 'I') {
            await scwin.search();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30342.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Save_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Save_onclick = async function() {
    try {
        await scwin.save();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30342.btn_Save_onclick" });
    }
};

/**
 * @method
 * @name btn_Delete_onclick
 * @description 「삭제」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Delete_onclick = function() {
    try {
        scwin.delete();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30342.btn_Delete_onclick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30342.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        await $c.win.alert(trs_Save);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30342.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        const msg = $c.stf.getMessageParam("MSG-A001", gLastJob);
        await $c.win.alert(msg);

        ////////////////
        if (scwin.mode === 'I') {
            let fr_fn_Search = $c.frame.path("../../").fn_search;
            frame.opener.close();
            await $c.win.closePopup();
            fr_fn_Search();
        } else {
            let fr_fn_Search = $c.frame.path("../").fn_search;
            fr_fn_Search();
            await $c.win.closePopup();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30342.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name grd_FILE_LIST_OnClick
 * @description grd_FILE_LIST 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_FILE_LIST_OnClick = function(row, colid) {
    try {
        fn_DownLoad(row, colid);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30342.grd_FILE_LIST_OnClick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name setNewMode
 * @description set New Mode 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setNewMode = async function() {
    const sbmOptions = {
        id : "sbm_dts_MASTER",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_MASTER=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    dts_MASTER.insertRow();
    scwin.setCode();
};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    url += "&CONTN_ID=" + scwin.contn_id;
    url += "&CONTN_GRP_ID=" + scwin.contn_grp_id;
    url += "&ANS_OBJ_CONTN_ID=" + scwin.ans_obj_contn_id;
    url += "&NOTI_OBJ_SYS_TP_CD=" + scwin.noti_obj_sys_tp_cd;
    url += "&SCREN_ID=" + "ULDSTF30342.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;

    // alert(url);
    const sbmOptions = {
        id : "sbm_dts_MASTER",
        action : "/VocQnA.do",
        ref : "",
        target : "dts_MASTER=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {void}
 * @hidden N
 */
scwin.setCode = function() {
    if (scwin.mode === 'I') {
        scwin.key_row = frame.opener.scwin.key_row;
        scwin.isur_id = frame.opener.scwin.isur_id;
        scwin.corp_usr_tp_cd = frame.opener.scwin.corp_usr_tp_cd;
        scwin.contn_id = frame.opener.scwin.contn_id;
        scwin.contn_grp_id = frame.opener.scwin.contn_grp_id;
        scwin.ans_obj_contn_id = frame.opener.scwin.ans_obj_contn_id;
        scwin.noti_obj_sys_tp_cd = frame.opener.scwin.noti_obj_sys_tp_cd;
        scwin.ques_bz_tp_cd = frame.opener.scwin.ques_bz_tp_cd;
        scwin.opn_yn = frame.opener.scwin.opn_yn;
        btn_Delete.hide();
        txb_ISUR_CD.setValue(scwin.isur_id);
        txb_CORP_USR_TP_CD.setValue(scwin.corp_usr_tp_cd);
        txb_CONTN_ID.setValue(scwin.contn_id);
        txb_CONTN_GRP_ID.setValue(scwin.contn_grp_id);
        txb_ANS_OBJ_CONTN_ID.setValue(scwin.ans_obj_contn_id);
        txb_NOTI_OBJ_SYS_TP_CD.setValue(scwin.noti_obj_sys_tp_cd);
        txb_QUES_BZ_TP_CD.setValue(scwin.ques_bz_tp_cd);
        txb_QUESTR_NM.setValue(js_emp_nm);
        txb_OPN_YN.setValue(scwin.opn_yn);
    } else {
        scwin.key_row = frame.opener.scwin.key_row;
        scwin.contn_id = frame.opener.dts_qnaList.getCellData(scwin.key_row, "CONTN_ID");
        scwin.contn_grp_id = frame.opener.dts_qnaList.getCellData(scwin.key_row, "CONTN_GRP_ID");
        scwin.ans_obj_contn_id = frame.opener.dts_qnaList.getCellData(scwin.key_row, "ANS_OBJ_CONTN_ID");
        scwin.noti_obj_sys_tp_cd = frame.opener.dts_qnaList.getCellData(scwin.key_row, "NOTI_OBJ_SYS_TP_CD");
    }
    // alert("contn_id : " + contn_id + " : contn_grp_id : " + contn_grp_id + " : ans_obj_contn_id : " + ans_obj_contn_id + " : contn_depth : " + contn_depth + " : intl_acntg_bas_bbs_tp_cd : " + intl_acntg_bas_bbs_tp_cd);

};

/**
 * @method
 * @name initPage
 * @description init Page 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.initPage = async function() {
    if (scwin.mode === 'I') {
        // 미답변상태
        await scwin.setNewMode();
    } else {
        // 답변상태

    }

    //*
    panel_Hidden.hide();
    //*/

};

/**
 * @method
 * @name readmode
 * @description 색상변화와 리드온리
 * @returns {void}
 * @hidden N
 */
scwin.readmode = function() {
    // 색상변화와 리드온리

};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    if (txb_QUES_TITLE.getValue() === '') {
        await $c.win.alert("제목을 입력해주세요.");
        txb_QUES_TITLE.focus();
        return false;
    }
    if (txa_QUES_CONTN.getValue() === '') {
        await $c.win.alert("내용을 입력해주세요.");
        txa_QUES_CONTN.focus();
        return false;
    }
    txb_QUESTR_ID.setValue(scwin.gEmpNo);
    txb_QUES_ANS_TP_CD.setValue('2'); // 2:답변

    if (scwin.mode === 'I') {
        scwin.insert();
    } else {
        scwin.update();
    }
};

/**
 * @method
 * @name insert
 * @description insert 처리
 * @returns {void}
 * @hidden N
 */
scwin.insert = function() {
    let res = window.confirm("[저장]하시겠습니까?");
    if (res) {
        gLastJob = "저장";
        let url = "/VocQnA.do?method=insertVocQnA" + "&SCREN_ID=" + "ULDSTF30342.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        // alert(dts_MASTER.Text);

        ///*
        trs_Save.Action = url;
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pInput=dts_MASTER)";
        trs_Save.post();
        //*/

    }
};

/**
 * @method
 * @name update
 * @description update 처리
 * @returns {void}
 * @hidden N
 */
scwin.update = function() {
    let res = window.confirm("[수정]하시겠습니까?");
    if (res) {
        gLastJob = "수정";
        let url = "/VocQnA.do?method=updateVocQnA" + "&SCREN_ID=" + "ULDSTF30342.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
        // alert(dts_MASTER.Text);

        trs_Save.Action = url;
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pInput=dts_MASTER)";
        trs_Save.post();
    }
};

/**
 * @method
 * @name delete
 * @description delete 처리
 * @returns {void}
 * @hidden N
 */
scwin.delete = function() {
    let res = window.confirm("[삭제]하시겠습니까?");
    if (res) {
        dts_MASTER.setCellData(1, "DEL_YN", 'Y');
        gLastJob = "삭제";
        let url = "/VocQnA.do?method=deleteVocQnA" + "&SCREN_ID=" + "ULDSTF30342.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
        // alert(dts_MASTER.Text);
        trs_Save.Action = url;
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pInput=dts_MASTER)";
        trs_Save.post();
    }
};
